import React, { useState, useEffect } from "react";
import MatchingGame from "../components/games/MatchingGame";
import QuizGame from "../components/games/QuizGame";
import PuzzleGame from "../components/games/PuzzleGame";
import MemoryGame from "../components/games/MemoryGame";
import DragDropGame from "../components/games/DragDropGame";
import BuilderGame from "../components/games/BuilderGame";
import ReactionGame from "../components/games/ReactionGame";

function Games({ onGameWin }) {
  const [user, setUser] = useState(null);
  const [selectedTopic, setSelectedTopic] = useState("Biology");
  const [isLoading, setIsLoading] = useState(true);
  const [playerCoins, setPlayerCoins] = useState(0);
  const [activeGame, setActiveGame] = useState(null);
  const [gameType, setGameType] = useState(null);
  const [unlockedGames, setUnlockedGames] = useState(new Set());

  useEffect(() => {
    console.log("🎮 Games component mounted");
    const savedUser = localStorage.getItem("user");
    console.log("🎮 User from localStorage:", savedUser);

    if (savedUser) {
      try {
        const parsedUser = JSON.parse(savedUser);
        console.log("🎮 Parsed user:", parsedUser);
        setUser(parsedUser);
        setPlayerCoins(parsedUser.coins || 0);
      } catch (e) {
        console.error("🎮 Error parsing user:", e);
      }
    }

    // Load unlocked games from localStorage
    const savedUnlocked = localStorage.getItem("unlockedGames");
    if (savedUnlocked) {
      try {
        const unlockedArray = JSON.parse(savedUnlocked);
        setUnlockedGames(new Set(unlockedArray));
      } catch (e) {
        console.error("🎮 Error loading unlocked games:", e);
      }
    }

    setIsLoading(false);
  }, []);

  // Comprehensive game data - 10 games per science topic
  // First game of each lesson is FREE (coin_cost: 0)
  // Other games cost coins and reward more based on difficulty
  const gamesByTopic = {
    Biology: [
      { id: 1, game_number: 1, title: "Cell Structure Master", description: "Identify cell organelles and their functions. Match organelles to their descriptions.", lesson: "Introduction to Biology", base_reward: 15, coin_cost: 0, difficulty: "Easy" },
      { id: 2, game_number: 2, title: "Photosynthesis Puzzle", description: "Guide plants through photosynthesis. Learn light and dark reactions.", lesson: "Photosynthesis & Cellular Respiration", base_reward: 30, coin_cost: 10, difficulty: "Medium" },
      { id: 3, game_number: 3, title: "Evolution Match", description: "Connect species to their evolutionary adaptations. Understand natural selection.", lesson: "Evolution & Natural Selection", base_reward: 60, coin_cost: 15, difficulty: "Medium" },
      { id: 4, game_number: 4, title: "Genetics Inheritance", description: "Create Punnett squares to predict offspring traits.", lesson: "Genetics & Heredity", base_reward: 120, coin_cost: 20, difficulty: "Hard" },
      { id: 5, game_number: 5, title: "DNA Sequencer", description: "Arrange DNA bases in correct order. Learn genetic coding.", lesson: "DNA & Molecular Biology", base_reward: 240, coin_cost: 25, difficulty: "Hard" },
      { id: 6, game_number: 6, title: "Ecosystem Builder", description: "Create balanced ecosystems with food chains and energy flow.", lesson: "Ecology & Ecosystems", base_reward: 480, coin_cost: 30, difficulty: "Medium" },
      { id: 7, game_number: 7, title: "Population Simulator", description: "Manage population growth and limiting factors.", lesson: "Population Dynamics", base_reward: 960, coin_cost: 35, difficulty: "Hard" },
      { id: 8, game_number: 8, title: "Anatomy Labeler", description: "Label human body systems and organs correctly.", lesson: "Human Body Systems", base_reward: 1920, coin_cost: 40, difficulty: "Medium" },
      { id: 9, game_number: 9, title: "Immune Response", description: "Learn how immune cells fight infections and disease.", lesson: "Immune System & Disease", base_reward: 3840, coin_cost: 45, difficulty: "Hard" },
      { id: 10, game_number: 10, title: "Taxonomy Challenge", description: "Classify organisms using the binomial nomenclature system.", lesson: "Classification & Taxonomy", base_reward: 7680, coin_cost: 50, difficulty: "Expert" },
    ],
    Chemistry: [
      { id: 11, game_number: 1, title: "Periodic Table Master", description: "Learn elements, symbols, and periodic trends.", lesson: "Atomic Structure & Periodic Table", base_reward: 15, coin_cost: 0, difficulty: "Easy" },
      { id: 12, game_number: 2, title: "Electron Configuration", description: "Fill electron shells with correct orbital arrangement.", lesson: "Electrons & Energy Levels", base_reward: 30, coin_cost: 10, difficulty: "Medium" },
      { id: 13, game_number: 3, title: "Bonding Builder", description: "Form ionic, covalent, and metallic bonds.", lesson: "Chemical Bonding", base_reward: 60, coin_cost: 15, difficulty: "Hard" },
      { id: 14, game_number: 4, title: "Molecule Constructor", description: "Build molecules from atoms. Learn molecular structures.", lesson: "Molecular Geometry", base_reward: 120, coin_cost: 20, difficulty: "Medium" },
      { id: 15, game_number: 5, title: "Reaction Balancer", description: "Balance chemical equations and identify reaction types.", lesson: "Chemical Reactions", base_reward: 240, coin_cost: 25, difficulty: "Hard" },
      { id: 16, game_number: 6, title: "Stoichiometry Solver", description: "Calculate molar relationships in chemical reactions.", lesson: "Stoichiometry & Moles", base_reward: 480, coin_cost: 30, difficulty: "Expert" },
      { id: 17, game_number: 7, title: "Acid-Base Analyzer", description: "Determine pH and classify acids, bases, and salts.", lesson: "Acids, Bases & pH", base_reward: 960, coin_cost: 35, difficulty: "Hard" },
      { id: 18, game_number: 8, title: "Oxidation Redux", description: "Identify oxidation and reduction reactions.", lesson: "Redox & Electrochemistry", base_reward: 1920, coin_cost: 40, difficulty: "Hard" },
      { id: 19, game_number: 9, title: "Thermochemistry Lab", description: "Calculate enthalpy and predict reaction energy changes.", lesson: "Thermochemistry & Energy", base_reward: 3840, coin_cost: 45, difficulty: "Expert" },
      { id: 20, game_number: 10, title: "Kinetics Inspector", description: "Understand reaction rates and activation energy.", lesson: "Reaction Kinetics", base_reward: 7680, coin_cost: 50, difficulty: "Hard" },
    ],
    Physics: [
      { id: 21, game_number: 1, title: "Force & Motion", description: "Apply Newton's laws to solve physics problems.", lesson: "Forces & Newton's Laws", base_reward: 15, coin_cost: 0, difficulty: "Easy" },
      { id: 22, game_number: 2, title: "Kinematics Calculator", description: "Calculate distance, velocity, and acceleration.", lesson: "Motion & Kinematics", base_reward: 30, coin_cost: 10, difficulty: "Medium" },
      { id: 23, game_number: 3, title: "Energy Transformer", description: "Convert between kinetic and potential energy.", lesson: "Work & Energy", base_reward: 60, coin_cost: 15, difficulty: "Medium" },
      { id: 24, game_number: 4, title: "Momentum Master", description: "Calculate momentum and collisions.", lesson: "Momentum & Impulse", base_reward: 120, coin_cost: 20, difficulty: "Hard" },
      { id: 25, game_number: 5, title: "Circular Motion", description: "Solve centripetal force and rotational problems.", lesson: "Circular Motion & Gravity", base_reward: 240, coin_cost: 25, difficulty: "Hard" },
      { id: 26, game_number: 6, title: "Wave Simulator", description: "Create and analyze waves, frequency, and wavelength.", lesson: "Waves & Sound", base_reward: 480, coin_cost: 30, difficulty: "Medium" },
      { id: 27, game_number: 7, title: "Optics Explorer", description: "Learn reflection, refraction, and light properties.", lesson: "Light & Optics", base_reward: 960, coin_cost: 35, difficulty: "Hard" },
      { id: 28, game_number: 8, title: "Electricity Circuits", description: "Build circuits and calculate current, voltage, resistance.", lesson: "Electricity & Circuits", base_reward: 1920, coin_cost: 40, difficulty: "Hard" },
      { id: 29, game_number: 9, title: "Magnetism Field", description: "Visualize magnetic fields and electromagnetic forces.", lesson: "Magnetism & Electromagnetism", base_reward: 3840, coin_cost: 45, difficulty: "Hard" },
      { id: 30, game_number: 10, title: "Quantum Quest", description: "Explore quantum mechanics and atomic models.", lesson: "Modern Physics & Quantum", base_reward: 7680, coin_cost: 50, difficulty: "Expert" },
    ],
    "Environmental Science": [
      { id: 31, game_number: 1, title: "Biome Explorer", description: "Identify biomes and their characteristics worldwide.", lesson: "Earth's Biomes", base_reward: 15, coin_cost: 0, difficulty: "Easy" },
      { id: 32, game_number: 2, title: "Water Cycle Tracker", description: "Follow water through evaporation, condensation, precipitation.", lesson: "Water Cycle & Hydrosphere", base_reward: 30, coin_cost: 10, difficulty: "Medium" },
      { id: 33, game_number: 3, title: "Nutrient Cycling", description: "Track nitrogen, phosphorus, and carbon cycles.", lesson: "Nutrient Cycles", base_reward: 60, coin_cost: 15, difficulty: "Medium" },
      { id: 34, game_number: 4, title: "Weathering & Erosion", description: "Understand rock formation and soil development.", lesson: "Rocks, Minerals & Weathering", base_reward: 120, coin_cost: 20, difficulty: "Medium" },
      { id: 35, game_number: 5, title: "Weather Predictor", description: "Analyze weather patterns and atmospheric conditions.", lesson: "Weather & Atmosphere", base_reward: 240, coin_cost: 25, difficulty: "Hard" },
      { id: 36, game_number: 6, title: "Climate Modeler", description: "Simulate climate scenarios and predict changes.", lesson: "Climate & Climate Change", base_reward: 480, coin_cost: 30, difficulty: "Hard" },
      { id: 37, game_number: 7, title: "Conservation Hero", description: "Make decisions to protect endangered species and habitats.", lesson: "Biodiversity & Conservation", base_reward: 960, coin_cost: 35, difficulty: "Hard" },
      { id: 38, game_number: 8, title: "Pollution Fighter", description: "Identify pollution types and environmental solutions.", lesson: "Pollution & Environmental Issues", base_reward: 1920, coin_cost: 40, difficulty: "Hard" },
      { id: 39, game_number: 9, title: "Renewable Energy", description: "Learn about solar, wind, and sustainable energy sources.", lesson: "Renewable & Sustainable Resources", base_reward: 3840, coin_cost: 45, difficulty: "Hard" },
      { id: 40, game_number: 10, title: "Ecosystem Manager", description: "Balance human needs with ecosystem health.", lesson: "Human Impact & Sustainability", base_reward: 7680, coin_cost: 50, difficulty: "Expert" },
    ],
    Economics: [
      { id: 41, game_number: 1, title: "Supply & Demand", description: "Balance markets and find equilibrium prices.", lesson: "Supply, Demand & Markets", base_reward: 15, coin_cost: 0, difficulty: "Easy" },
      { id: 42, game_number: 2, title: "Business Tycoon", description: "Run a virtual business with profit and loss.", lesson: "Business & Entrepreneurship", base_reward: 30, coin_cost: 10, difficulty: "Medium" },
      { id: 43, game_number: 3, title: "Budget Manager", description: "Create household and government budgets.", lesson: "Personal & Government Finance", base_reward: 60, coin_cost: 15, difficulty: "Medium" },
      { id: 44, game_number: 4, title: "Investment Trader", description: "Buy and sell stocks and build a portfolio.", lesson: "Stocks & Investments", base_reward: 120, coin_cost: 20, difficulty: "Hard" },
      { id: 45, game_number: 5, title: "GDP Calculator", description: "Measure economic growth and productivity.", lesson: "Macroeconomics & GDP", base_reward: 240, coin_cost: 25, difficulty: "Hard" },
      { id: 46, game_number: 6, title: "Inflation Monitor", description: "Manage inflation, unemployment, and interest rates.", lesson: "Inflation & Monetary Policy", base_reward: 480, coin_cost: 30, difficulty: "Hard" },
      { id: 47, game_number: 7, title: "Trade Navigator", description: "Understand international trade and tariffs.", lesson: "International Trade", base_reward: 960, coin_cost: 35, difficulty: "Hard" },
      { id: 48, game_number: 8, title: "Tax Planner", description: "Calculate taxes and optimize financial strategy.", lesson: "Taxation & Tax Planning", base_reward: 1920, coin_cost: 40, difficulty: "Hard" },
      { id: 49, game_number: 9, title: "Labor Economics", description: "Understand wages, employment, and worker rights.", lesson: "Labor Economics", base_reward: 3840, coin_cost: 45, difficulty: "Hard" },
      { id: 50, game_number: 10, title: "Economic Systems", description: "Compare capitalism, socialism, and mixed economies.", lesson: "Economic Systems & Theory", base_reward: 7680, coin_cost: 50, difficulty: "Expert" },
    ],
    History: [
      { id: 51, game_number: 1, title: "Timeline Constructor", description: "Arrange historical events in correct order.", lesson: "Ancient Civilizations", base_reward: 15, coin_cost: 0, difficulty: "Easy" },
      { id: 52, game_number: 2, title: "Medieval Kingdoms", description: "Learn about feudalism and medieval society.", lesson: "Medieval Period", base_reward: 30, coin_cost: 10, difficulty: "Medium" },
      { id: 53, game_number: 3, title: "Renaissance Trivia", description: "Explore art, science, and culture rebirth.", lesson: "Renaissance & Reformation", base_reward: 60, coin_cost: 15, difficulty: "Medium" },
      { id: 54, game_number: 4, title: "Age of Exploration", description: "Track explorers and discovery of new lands.", lesson: "Age of Exploration", base_reward: 120, coin_cost: 20, difficulty: "Medium" },
      { id: 55, game_number: 5, title: "Revolution Puzzle", description: "Understand causes and effects of major revolutions.", lesson: "Revolutionary Movements", base_reward: 240, coin_cost: 25, difficulty: "Hard" },
      { id: 56, game_number: 6, title: "Industrial Era", description: "Learn about industrialization and social changes.", lesson: "Industrial Revolution", base_reward: 480, coin_cost: 30, difficulty: "Hard" },
      { id: 57, game_number: 7, title: "World War Historian", description: "Study major conflicts and their impacts.", lesson: "20th Century Wars", base_reward: 960, coin_cost: 35, difficulty: "Hard" },
      { id: 58, game_number: 8, title: "Cold War Strategies", description: "Understand geopolitical tensions and diplomacy.", lesson: "Cold War Period", base_reward: 1920, coin_cost: 40, difficulty: "Hard" },
      { id: 59, game_number: 9, title: "Modern History Map", description: "Trace contemporary historical movements and events.", lesson: "Modern History & Globalization", base_reward: 3840, coin_cost: 45, difficulty: "Hard" },
      { id: 60, game_number: 10, title: "Historical Figures", description: "Match leaders and thinkers with their achievements.", lesson: "Key Historical Figures", base_reward: 7680, coin_cost: 50, difficulty: "Expert" },
    ],
    "Human Geography": [
      { id: 61, game_number: 1, title: "Map Master", description: "Identify countries, capitals, and geographic features.", lesson: "World Geography & Maps", base_reward: 15, coin_cost: 0, difficulty: "Easy" },
      { id: 62, game_number: 2, title: "Culture Explorer", description: "Learn about different cultures and traditions worldwide.", lesson: "Cultural Geography", base_reward: 30, coin_cost: 10, difficulty: "Medium" },
      { id: 63, game_number: 3, title: "Population Analyzer", description: "Study population distribution and demographics.", lesson: "Population & Demographics", base_reward: 60, coin_cost: 15, difficulty: "Medium" },
      { id: 64, game_number: 4, title: "Urban Planner", description: "Design sustainable cities and urban spaces.", lesson: "Urban Geography", base_reward: 120, coin_cost: 20, difficulty: "Hard" },
      { id: 65, game_number: 5, title: "Economic Regions", description: "Understand global economic zones and trade.", lesson: "Economic Geography", base_reward: 240, coin_cost: 25, difficulty: "Hard" },
      { id: 66, game_number: 6, title: "Political Boundaries", description: "Learn geopolitics and international borders.", lesson: "Political Geography", base_reward: 480, coin_cost: 30, difficulty: "Hard" },
      { id: 67, game_number: 7, title: "Resource Manager", description: "Manage natural resources sustainably.", lesson: "Natural Resources & Environment", base_reward: 960, coin_cost: 35, difficulty: "Hard" },
      { id: 68, game_number: 8, title: "Migration Tracker", description: "Understand human migration and diaspora.", lesson: "Migration & Diaspora", base_reward: 1920, coin_cost: 40, difficulty: "Hard" },
      { id: 69, game_number: 9, title: "Climate & Landscape", description: "Explore climate zones and landforms.", lesson: "Climate & Landforms", base_reward: 3840, coin_cost: 45, difficulty: "Hard" },
      { id: 70, game_number: 10, title: "Development Compass", description: "Compare economic development across regions.", lesson: "Development & Inequality", base_reward: 7680, coin_cost: 50, difficulty: "Expert" },
    ],
    Psychology: [
      { id: 71, game_number: 1, title: "Cognitive Bias Detector", description: "Identify common thinking patterns and biases.", lesson: "Introduction to Psychology", base_reward: 15, coin_cost: 0, difficulty: "Easy" },
      { id: 72, game_number: 2, title: "Memory Mastermind", description: "Learn and test different types of memory.", lesson: "Sensation & Perception", base_reward: 30, coin_cost: 10, difficulty: "Medium" },
      { id: 73, game_number: 3, title: "Learning Pathways", description: "Understand classical and operant conditioning.", lesson: "Learning & Conditioning", base_reward: 60, coin_cost: 15, difficulty: "Medium" },
      { id: 74, game_number: 4, title: "Motivation Motivator", description: "Explore needs, drives, and motivation theories.", lesson: "Motivation & Emotion", base_reward: 120, coin_cost: 20, difficulty: "Hard" },
      { id: 75, game_number: 5, title: "Personality Puzzle", description: "Learn personality theories and assessment.", lesson: "Personality & Development", base_reward: 240, coin_cost: 25, difficulty: "Hard" },
      { id: 76, game_number: 6, title: "Social Dynamics", description: "Understand group behavior and social influence.", lesson: "Social Psychology", base_reward: 480, coin_cost: 30, difficulty: "Hard" },
      { id: 77, game_number: 7, title: "Mental Health Guide", description: "Learn about disorders and mental wellness.", lesson: "Mental Health & Disorders", base_reward: 960, coin_cost: 35, difficulty: "Hard" },
      { id: 78, game_number: 8, title: "Therapy Techniques", description: "Understand psychological treatments and therapy.", lesson: "Therapies & Interventions", base_reward: 1920, coin_cost: 40, difficulty: "Hard" },
      { id: 79, game_number: 9, title: "Neuroscience Quest", description: "Explore brain structure and neurotransmitters.", lesson: "Biopsychology & Neuroscience", base_reward: 3840, coin_cost: 45, difficulty: "Hard" },
      { id: 80, game_number: 10, title: "Research Methods", description: "Learn experimental design and statistical analysis.", lesson: "Research Methods & Statistics", base_reward: 7680, coin_cost: 50, difficulty: "Expert" },
    ],
  };

  const topicGames = gamesByTopic[selectedTopic] || [];

  // Game content library - maps game IDs to actual game data
  const gameContentLibrary = {
    // BIOLOGY GAMES (1-10)
    1: {
      type: "quiz",
      title: "Cell Structure Master",
      description: "Test your knowledge of cell organelles and their functions",
      questions: [
        {
          question: "Which organelle is responsible for producing energy in the cell?",
          options: ["Nucleus", "Mitochondria", "Ribosome", "Chloroplast"],
          correct: 1,
          explanation: "Mitochondria are the powerhouse of the cell, producing ATP energy"
        },
        {
          question: "What is the primary function of the nucleus?",
          options: ["Protein synthesis", "Store and control genetic information", "Energy production", "Fat storage"],
          correct: 1,
          explanation: "The nucleus contains DNA and controls all cellular functions"
        },
        {
          question: "Which organelle is found ONLY in plant cells?",
          options: ["Mitochondria", "Golgi apparatus", "Chloroplast", "Ribosome"],
          correct: 2,
          explanation: "Chloroplasts are unique to plant cells and conduct photosynthesis"
        },
        {
          question: "What do ribosomes synthesize?",
          options: ["Lipids", "Carbohydrates", "Proteins", "Nucleic acids"],
          correct: 2,
          explanation: "Ribosomes are the sites of protein synthesis in all cells"
        },
        {
          question: "What is the function of the cell membrane?",
          options: ["Energy production", "Protein synthesis", "Control what enters and exits the cell", "DNA storage"],
          correct: 2,
          explanation: "The cell membrane controls transport of materials in and out of the cell"
        }
      ]
    },
    2: {
      type: "quiz",
      title: "Photosynthesis Puzzle",
      description: "Master light and dark reactions in photosynthesis",
      questions: [
        {
          question: "What is the main purpose of photosynthesis?",
          options: ["Release oxygen", "Convert light energy to chemical energy", "Produce carbon dioxide", "Break down glucose"],
          correct: 1,
          explanation: "Photosynthesis converts light energy into glucose, a usable chemical energy"
        },
        {
          question: "Where does the light-dependent reaction occur?",
          options: ["Stroma", "Thylakoid membrane", "Mitochondria", "Ribosome"],
          correct: 1,
          explanation: "Light reactions occur in the thylakoid membranes of chloroplasts"
        },
        {
          question: "What is the primary pigment that absorbs light?",
          options: ["Xanthophyll", "Chlorophyll", "Carotenoid", "Hemoglobin"],
          correct: 1,
          explanation: "Chlorophyll is the main photosynthetic pigment that absorbs light"
        },
        {
          question: "What are the products of the light-dependent reactions?",
          options: ["Glucose and oxygen", "ATP, NADPH, and oxygen", "Carbon dioxide and water", "Glucose and ATP"],
          correct: 1,
          explanation: "Light reactions produce ATP and NADPH as energy carriers, releasing oxygen"
        },
        {
          question: "The Calvin cycle (dark reaction) requires which molecule to produce glucose?",
          options: ["Light energy", "Oxygen", "Carbon dioxide", "Chlorophyll"],
          correct: 2,
          explanation: "The Calvin cycle uses CO₂, ATP, and NADPH to synthesize glucose"
        }
      ]
    },
    3: {
      type: "quiz",
      title: "Evolution Match",
      description: "Understand natural selection and evolutionary adaptation",
      questions: [
        {
          question: "Which scientist developed the theory of evolution by natural selection?",
          options: ["Jean Lamarck", "Charles Darwin", "Gregor Mendel", "Stephen Jay Gould"],
          correct: 1,
          explanation: "Charles Darwin proposed natural selection as the mechanism of evolution"
        },
        {
          question: "What is natural selection?",
          options: ["Organisms changing intentionally", "Traits making organisms better adapted survive and reproduce", "Random changes in organisms", "Divine creation of species"],
          correct: 1,
          explanation: "Natural selection favors organisms with advantageous traits"
        },
        {
          question: "Which provides evidence for evolution?",
          options: ["Fossil records only", "Homologous structures only", "Fossil records, homologous structures, and DNA similarity", "Religious texts"],
          correct: 2,
          explanation: "Fossils, comparative anatomy, and molecular evidence all support evolution"
        },
        {
          question: "What is an adaptation?",
          options: ["A random mutation", "A trait that helps an organism survive in its environment", "A learned behavior", "A disease resistance"],
          correct: 1,
          explanation: "Adaptations are heritable traits that improve survival and reproduction"
        },
        {
          question: "How long has evolution been occurring on Earth?",
          options: ["Thousands of years", "Millions of years", "Billions of years", "Hundreds of years"],
          correct: 2,
          explanation: "Evolution has been occurring for approximately 3.8 billion years"
        }
      ]
    },
    4: {
      type: "quiz",
      title: "Genetics Inheritance",
      description: "Master Mendelian genetics and heredity patterns",
      questions: [
        {
          question: "What is a gene?",
          options: ["A type of protein", "A segment of DNA that codes for a trait", "A chromosome", "An amino acid"],
          correct: 1,
          explanation: "A gene is a specific DNA sequence that codes for a protein or trait"
        },
        {
          question: "What are alleles?",
          options: ["Different versions of a gene", "Mutations only", "Dominant traits", "Recessive traits"],
          correct: 0,
          explanation: "Alleles are different versions of the same gene at a locus"
        },
        {
          question: "If both parents are heterozygous (Aa) for a trait, what percentage of offspring will be homozygous?",
          options: ["25%", "50%", "75%", "100%"],
          correct: 0,
          explanation: "In Aa × Aa cross: 25% AA, 50% Aa, 25% aa = 50% homozygous"
        },
        {
          question: "What is the phenotype?",
          options: ["The genetic makeup", "The observable characteristics", "The DNA sequence", "The protein structure"],
          correct: 1,
          explanation: "Phenotype is the observable physical or biochemical characteristics"
        },
        {
          question: "What is codominance?",
          options: ["One allele masks another", "Both alleles are fully expressed", "A recessive allele expressing", "Mutation in both alleles"],
          correct: 1,
          explanation: "Codominance occurs when both alleles are fully expressed in the heterozygote"
        }
      ]
    },
    5: {
      type: "quiz",
      title: "DNA Sequencer",
      description: "Understand DNA structure and genetic coding",
      questions: [
        {
          question: "What does DNA stand for?",
          options: ["Deoxyribonucleic Acid", "Diribose Nucleic Acid", "Dynamic Neon Amino", "Dual Nitrogen Array"],
          correct: 0,
          explanation: "DNA = Deoxyribonucleic Acid, the molecule carrying genetic information"
        },
        {
          question: "What are the four nitrogenous bases in DNA?",
          options: ["A, T, U, G", "A, T, C, G", "A, T, C, U", "G, C, P, S"],
          correct: 1,
          explanation: "The four bases are Adenine, Thymine, Cytosine, and Guanine"
        },
        {
          question: "Which base pairs with Guanine in DNA?",
          options: ["Adenine", "Thymine", "Cytosine", "Uracil"],
          correct: 2,
          explanation: "Guanine (G) pairs with Cytosine (C) in DNA through 3 hydrogen bonds"
        },
        {
          question: "What is the shape of DNA?",
          options: ["Single helix", "Double helix", "Triple helix", "Circular"],
          correct: 1,
          explanation: "DNA has a double helix structure, discovered by Watson and Crick"
        },
        {
          question: "How many base pairs are in the human genome?",
          options: ["1 million", "100 million", "3 billion", "30 billion"],
          correct: 2,
          explanation: "The human genome contains approximately 3 billion base pairs"
        }
      ]
    },
    6: {
      type: "quiz",
      title: "Ecosystem Builder",
      description: "Understand food chains, energy flow, and ecosystem relationships",
      questions: [
        {
          question: "What are producers in an ecosystem?",
          options: ["Herbivores", "Decomposers", "Plants that make their own food", "Carnivores"],
          correct: 2,
          explanation: "Producers are autotrophs (plants) that create energy from the sun"
        },
        {
          question: "How much energy is transferred from one trophic level to the next?",
          options: ["50%", "25%", "10%", "90%"],
          correct: 2,
          explanation: "Approximately 10% of energy transfers to the next level; 90% is lost"
        },
        {
          question: "Which organisms break down dead matter and return nutrients to soil?",
